CREATE TABLE promo_images(id TEXT NOT NULL,tenant_id TEXT NOT NULL,owner_id TEXT NOT NULL,kind TEXT NOT NULL,mime TEXT,width INTEGER,height INTEGER,parts INTEGER NOT NULL DEFAULT 0,part_keys TEXT NOT NULL DEFAULT '[]',bytes INTEGER NOT NULL DEFAULT 0,ready INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(id));
